import { gaussian, hashString, seededRandom } from "./random";
import { getTicker } from "./tickers";
import { dayIndex } from "./time";

/**
 * The simulated price feed.
 *
 * Each symbol gets one closing price per day, generated by a seeded random walk
 * that follows a gently rising trend line. Same symbol + same day = same price,
 * everywhere, forever. That keeps charts, trades and portfolios consistent.
 *
 * To plug in real market data later, replace these functions with calls to a
 * data provider (Polygon, Alpaca, Finnhub...). Nothing else needs to know.
 */

/** The day on which each ticker's listed `price` sits exactly on its trend line. */
const ANCHOR_DAY = dayIndex(Date.UTC(2026, 9, 1));
/** The trend line rises about 18% a year. */
const YEARLY_GROWTH = 0.18;
/** How strongly prices are pulled back toward the trend each day (0 = never). */
const PULL_TO_TREND = 0.03;

function trendPrice(symbol: string, day: number): number {
  return getTicker(symbol).price * Math.exp((YEARLY_GROWTH / 365) * (day - ANCHOR_DAY));
}

// Generated history, kept so each day is only computed once.
const closesBySymbol = new Map<string, number[]>();

/** The closing price of `symbol` on simulated day `day`. */
export function closeOn(symbol: string, day: number): number {
  const target = Math.max(0, day);
  let closes = closesBySymbol.get(symbol);
  if (!closes) {
    closes = [trendPrice(symbol, 0)];
    closesBySymbol.set(symbol, closes);
  }

  const { volatility } = getTicker(symbol);
  const seed = hashString(symbol);
  while (closes.length <= target) {
    const d = closes.length;
    const previous = closes[d - 1];
    const shock = gaussian(seededRandom(seed + d * 7919));
    const distanceFromTrend = Math.log(previous / trendPrice(symbol, d));
    closes.push(previous * Math.exp(volatility * shock - PULL_TO_TREND * distanceFromTrend));
  }
  return closes[target];
}

/** Daily closes from `fromDay` to `toDay`, inclusive. */
export function closesBetween(symbol: string, fromDay: number, toDay: number): number[] {
  const prices: number[] = [];
  for (let day = fromDay; day <= toDay; day++) prices.push(closeOn(symbol, day));
  return prices;
}

/**
 * A smooth intraday path for one day: starts at yesterday's close and ends
 * exactly at today's close. Used for the "1D" charts.
 */
export function intradayPrices(symbol: string, day: number, points = 48): number[] {
  const open = closeOn(symbol, day - 1);
  const close = closeOn(symbol, day);
  const random = seededRandom(hashString(symbol) ^ (day * 104729));
  const stepSize = getTicker(symbol).volatility / Math.sqrt(points);

  const walk = [0];
  for (let i = 1; i <= points; i++) walk.push(walk[i - 1] + stepSize * gaussian(random));

  // Bend the walk so its last point lands on the real close.
  const correction = Math.log(close / open) - walk[points];
  return walk.map((value, i) => open * Math.exp(value + (correction * i) / points));
}

/**
 * One live "tick": nudges a price by a tiny random amount, while gently pulling
 * it back toward today's close so it never wanders far. Live ticks are only
 * for show, so plain Math.random is fine here.
 */
export function nextTick(symbol: string, current: number, todayClose: number): number {
  const shock = gaussian(Math.random);
  const distance = Math.log(current / todayClose);
  return current * Math.exp(getTicker(symbol).volatility * 0.05 * shock - 0.08 * distance);
}
